CREATE DATABASE IF NOT EXISTS donations_source;
USE donations_source;
CREATE TABLE IF NOT EXISTS corez_donatur (id_donatur BIGINT PRIMARY KEY, donatur VARCHAR(255), hp VARCHAR(50), email VARCHAR(255));
CREATE TABLE IF NOT EXISTS setting_program (id_program VARCHAR(50) PRIMARY KEY, program VARCHAR(255));
CREATE TABLE IF NOT EXISTS fins_coa (coa VARCHAR(50) PRIMARY KEY, nama_coa VARCHAR(100));
CREATE TABLE IF NOT EXISTS corez_transaksi (id_transaksi BIGINT PRIMARY KEY AUTO_INCREMENT,id_donatur BIGINT,transaksi DECIMAL(18,2),tgl_transaksi DATETIME,coa_debet VARCHAR(50),id_program VARCHAR(50),INDEX idx_trx_donor_date(id_donatur,tgl_transaksi),INDEX idx_trx_date(tgl_transaksi));
